BEGIN;
SELECT pg_advisory_xact_lock(hashtext('atlas-authoring:person-registration-queue-canonical:v1'));
SET LOCAL lock_timeout='10s';

DO $atlas$
DECLARE
  v_bootstrap_needed boolean;
  v_total integer;
  v_pending integer;
  v_bound integer;
  v_missing integer;
  v_extra integer;
  v_duplicates integer;
  v_dangling integer;
  v_commerce integer;
  v_commerce_bound integer;
BEGIN
  SELECT NOT EXISTS (
    SELECT 1 FROM information_schema.columns
     WHERE table_schema='atlas_v2'
       AND table_name='person_candidate_registration_states'
       AND column_name='name'
  ) INTO v_bootstrap_needed;

  ALTER TABLE atlas_v2.person_candidate_registration_states
    ALTER COLUMN review_revision DROP NOT NULL,
    ADD COLUMN IF NOT EXISTS name text,
    ADD COLUMN IF NOT EXISTS lookup_names text[] NOT NULL DEFAULT '{}'::text[],
    ADD COLUMN IF NOT EXISTS representative_domain text,
    ADD COLUMN IF NOT EXISTS legacy_priority text,
    ADD COLUMN IF NOT EXISTS origin text,
    ADD COLUMN IF NOT EXISTS source_issue bigint,
    ADD COLUMN IF NOT EXISTS source_comment_id bigint,
    ADD COLUMN IF NOT EXISTS human_authorized_by_user boolean NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS admitted_at timestamptz NOT NULL DEFAULT now();

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
     WHERE conrelid=to_regclass('atlas_v2.person_candidate_registration_states')
       AND conname='person_candidate_registration_domain_ck'
  ) THEN
    ALTER TABLE atlas_v2.person_candidate_registration_states
      ADD CONSTRAINT person_candidate_registration_domain_ck
      CHECK (
        representative_domain IS NULL OR representative_domain IN (
          'governance','military','knowledge','technology',
          'commerce','culture','religion','exploration'
        )
      );
  END IF;

  IF v_bootstrap_needed THEN
    CREATE TEMP TABLE atlas_registration_queue_bootstrap ON COMMIT DROP AS
    SELECT
      item->>'candidate_id' AS candidate_id,
      item->>'name' AS name,
      COALESCE(ARRAY(SELECT jsonb_array_elements_text(item->'lookup_names')), '{}'::text[]) AS lookup_names,
      NULLIF(item->>'representative_domain','') AS representative_domain,
      NULLIF(item->>'legacy_priority','') AS legacy_priority,
      NULLIF(item->>'origin','') AS origin,
      NULLIF(item->>'source_issue','')::bigint AS source_issue,
      NULLIF(item->>'source_comment_id','')::bigint AS source_comment_id,
      COALESCE((item->>'human_authorized_by_user')::boolean,false) AS human_authorized_by_user,
      NULLIF(item->>'person_id','')::uuid AS person_id
    FROM jsonb_array_elements($queue$[{"candidate_id":"aoe2-ss-20260925-abdallah-ibn-yasin","name":"Abdallah ibn Yasin","lookup_names":["Abdallah ibn Yasin"],"representative_domain":"religion","legacy_priority":"SS","origin":"historical_queue","source_issue":1374,"source_comment_id":5825498864,"human_authorized_by_user":false,"person_id":"c4b0f1e9-722f-4507-8a27-bc4ee86a19de"},{"candidate_id":"aoe2-ss-20260925-ala-ad-din-muhammad-ii","name":"Ala ad-Din Muhammad II","lookup_names":["Ala ad-Din Muhammad II"],"representative_domain":"governance","legacy_priority":"SS","origin":"historical_queue","source_issue":1374,"source_comment_id":5825498864,"human_authorized_by_user":false,"person_id":"186aab39-b7d1-4cba-810b-eb7da6cf7d58"},{"candidate_id":"aoe2-ss-20260925-ala-ud-din-khalji","name":"Ala-ud-Din Khalji","lookup_names":["Ala-ud-Din Khalji"],"representative_domain":"governance","legacy_priority":"SS","origin":"historical_queue","source_issue":1374,"source_comment_id":5825498864,"human_authorized_by_user":false,"person_id":null},{"candidate_id":"aoe2-ss-20260925-alboin","name":"Alboin","lookup_names":["Alboin"],"representative_domain":"governance","legacy_priority":"SS","origin":"historical_queue","source_issue":1374,"source_comment_id":5825498864,"human_authorized_by_user":false,"person_id":"7e66a97e-2ebe-454b-8271-970defde582d"},{"candidate_id":"aoe2-ss-20260925-algirdas","name":"Algirdas","lookup_names":["Algirdas"],"representative_domain":"governance","legacy_priority":"SS","origin":"historical_queue","source_issue":1374,"source_comment_id":5825498864,"human_authorized_by_user":false,"person_id":"e0035e50-9f08-4a32-81c2-a9544b65ebde"},{"candidate_id":"aoe2-ss-20260925-ashikaga-takauji","name":"Ashikaga Takauji","lookup_names":["Ashikaga Takauji"],"representative_domain":"governance","legacy_priority":"SS","origin":"historical_queue","source_issue":1374,"source_comment_id":5825498864,"human_authorized_by_user":false,"person_id":"97981e09-e791-49d6-9dea-78d56e472102