human_authorized_by_user":true,"person_id":null},{"candidate_id":"commerce-20261003-050","name":"Talaat Harb","lookup_names":["Talaat Harb","Tal'at Harb","탈라트 하르브"],"representative_domain":"commerce","legacy_priority":null,"origin":"commerce_world_history_20261003","source_issue":null,"source_comment_id":null,"human_authorized_by_user":true,"person_id":null},{"candidate_id":"commerce-20261003-051","name":"Vehbi Koc","lookup_names":["Vehbi Koc","Vehbi Koç","베흐비 코치"],"representative_domain":"commerce","legacy_priority":null,"origin":"commerce_world_history_20261003","source_issue":null,"source_comment_id":null,"human_authorized_by_user":true,"person_id":null},{"candidate_id":"commerce-20261003-052","name":"Ernest Oppenheimer","lookup_names":["Ernest Oppenheimer","어니스트 오펜하이머"],"representative_domain":"commerce","legacy_priority":null,"origin":"commerce_world_history_20261003","source_issue":null,"source_comment_id":null,"human_authorized_by_user":true,"person_id":null},{"candidate_id":"commerce-20261003-053","name":"Irineu Evangelista de Sousa","lookup_names":["Irineu Evangelista de Sousa","Irineu Evangelista de Souza","Viscount of Maua","Viscount of Mauá","마우아 자작"],"representative_domain":"commerce","legacy_priority":null,"origin":"commerce_world_history_20261003","source_issue":null,"source_comment_id":null,"human_authorized_by_user":true,"person_id":null},{"candidate_id":"commerce-20261003-054","name":"Francesco Matarazzo","lookup_names":["Francesco Matarazzo","프란체스코 마타라초"],"representative_domain":"commerce","legacy_priority":null,"origin":"commerce_world_history_20261003","source_issue":null,"source_comment_id":null,"human_authorized_by_user":true,"person_id":null},{"candidate_id":"commerce-20261003-055","name":"Aristotle Onassis","lookup_names":["Aristotle Onassis","Aristotle Socrates Onassis","아리스토텔레스 오나시스"],"representative_domain":"commerce","legacy_priority":null,"origin":"commerce_world_history_20261003","source_issue":null,"source_comment_id":null,"human_authorized_by_user":true,"person_id":null}]$queue$::jsonb) AS item;

    SELECT count(*), count(*) FILTER (WHERE person_id IS NULL), count(*) FILTER (WHERE person_id IS NOT NULL)
      INTO v_total,v_pending,v_bound
      FROM atlas_registration_queue_bootstrap;
    SELECT count(*) - count(DISTINCT candidate_id)
      INTO v_duplicates
      FROM atlas_registration_queue_bootstrap;

    IF v_total <> 701 OR v_pending <> 393 OR v_bound <> 308 OR v_duplicates <> 0 THEN
      RAISE EXCEPTION 'REGISTRATION_QUEUE_BOOTSTRAP_BASELINE_DRIFT total=% pending=% bound=% duplicates=%',
        v_total,v_pending,v_bound,v_duplicates;
    END IF;

    INSERT INTO atlas_v2.person_candidate_registration_states(
      candidate_id,review_revision,registration_state,person_id,
      name,lookup_names,representative_domain,legacy_priority,origin,
      source_issue,source_comment_id,human_authorized_by_user
    )
    SELECT
      candidate_id,NULL,
      CASE WHEN person_id IS NULL THEN 'QUEUED' ELSE 'REGISTERED' END,
      person_id,name,lookup_names,representative_domain,legacy_priority,origin,
      source_issue,source_comment_id,human_authorized_by_user
    FROM atlas_registration_queue_bootstrap
    ON CONFLICT(candidate_id) DO UPDATE SET
      registration_state=EXCLUDED.registration_state,
      person_id=EXCLUDED.person_id,
      name=EXCLUDED.name,
      lookup_names=EXCLUDED.lookup_names,
      representative_domain=EXCLUDED.representative_domain,
      legacy_priority=EXCLUDED.legacy_priority,
      origin=EXCLUDED.origin,
      source_issue=EXCLUDED.source_issue,
      source_comment_id=EXCLUDED.source_comment_id,
      human_authorized_by_user=EXCLUDED.human_authorized_by_user,
      updated_at=now();

    SELECT count(*) INTO v_total FROM atlas_v2.person_candidate_registration_states;
    IF v_total <> 701 THEN
      RAISE EXCEPTION 'REGISTRATION_QUEUE_CANONICAL_TOTAL_DRIFT expected=701 actual=%',v_total;
    END IF;

    SELECT count(*) INTO v_missing
      FROM atlas_registration_queue_bootstrap b
     WHERE b.person_id IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM atlas_v2.person_candidate_registration_states q
          WHERE q.candidate_id=b.candidate_id AND q.person_id IS NULL
       );

    SELECT count(*) INTO v_extra
      FROM atlas_v2.person_candidate_registration_states q
     WHERE q.person_id IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM atlas_registration_queue_bootstrap b
          WHERE b.candidate_id=q.candidate_id AND b.person_id IS NULL
       );

    IF v_missing <> 0 OR v_extra <> 0 THEN
      RAISE EXCEPTION 'REGISTRATION_QUEUE_PENDING_SET_DRIFT missing=% extra=%',v_missing,v_extra;
    END IF;

    SELECT count(*) INTO v_dangling
      FROM atlas_v2.person_candidate_registration_states q
      LEFT JOIN atlas_v2.persons p ON p.id=q.person_id
     WHERE q.person_id IS NOT NULL AND p.id IS NULL;
    IF v_dangling <> 0 THEN
      RAISE EXCEPTION 'REGISTRATION_QUEUE_DANGLING_PERSON_IDS:%',v_dangling;
    END IF;

    SELECT count(*), count(*) FILTER (WHERE person_id IS NOT NULL)
      INTO v_commerce,v_commerce_bound
      FROM atlas_v2.person_candidate_registration_states
     WHERE candidate_id LIKE 'commerce-20261003-%';
    IF v_commerce <> 55 OR v_commerce_bound <> 0 THEN
      RAISE EXCEPTION 'REGISTRATION_QUEUE_COMMERCE_BASELINE_DRIFT total=% bound=%',
        v_commerce,v_commerce_bound;
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1 FROM atlas_v2.person_candidate_registration_states
     WHERE name IS NULL OR btrim(name)=''
  ) THEN
    RAISE EXCEPTION 'REGISTRATION_QUEUE_CANDIDATE_NAME_REQUIRED';
  END IF;

  ALTER TABLE atlas_v2.person_candidate_registration_states
    ALTER COLUMN name SET NOT NULL;
END
$atlas$;

CREATE INDEX IF NOT EXISTS person_candidate_registration_pending_idx
  ON atlas_v2.person_candidate_registration_states(candidate_id)
  WHERE person_id IS NULL;

COMMIT;
